// Well-known symbol: custom iteration
class Range {
  constructor(a, b) { this.a = a; this.b = b; }
  [Symbol.iterator]() {
    let i = this.a;
    return { next: () => i <= this.b ? { value: i++, done: false } : { done: true } };
  }
}
